head.script:
scwin.onpageload = function() {
    var jsonData = [{
            "label": "input",
            "code": "input"
        },
        {
            "label": "calendar",
            "code": "calendar"
        },
        {
            "label": "checkbox",
            "code": "checkbox"
        },
        {
            "label": "select",
            "code": "select"
        },
        {
            "label": "radio",
            "code": "radio"
        }
    ];
    dlt_select.setJSON(jsonData);
    var sel_sampleData = [{
            "codeLB": "축구",
            "codeVL": "1"
        },
        {
            "codeLB": "농구",
            "codeVL": "2"
        },
        {
            "codeLB": "야구",
            "codeVL": "3"
        },
        {
            "codeLB": "배구",
            "codeVL": "4"
        }
    ];
    sel_sample.setJSON(sel_sampleData);
    //dataList1.insertRow();
    //dataList1.getRowJSON
    var arr = [];
    for (var i = 0; i < 20; i++) {
        var j1 = {
            "col1": "checkbox"
        }
        arr.push(j1);
    }
    dataList1.setJSON(arr);
    scwin.flag = true;
    //grd.setCellMaxLength(0, 1, "4.2");
};
scwin.onpageunload = function() {};
scwin.grd_onviewchange = function(info) {
    console.log("scwin.grd_onviewchange", info);
    var inputType = info.newValue;
    //debugger;
    var obj = scwin.inputTypeCustomObj[inputType];
    if (inputType == "input") {
        obj["options"] = scwin.flag ? {
            allowChar: "0-9.",
            maxLength: "3.2"
        } : {
            allowChar: "",
            maxLength: "6.3"
        }
        scwin.flag = !scwin.flag;
    }
    console.log("obj: ", obj);
    grd.setCellInputType(info.rowIndex, "col2", obj);
    if (inputType === "input") {
        //grd.setCellMaxLength(info.rowIndex, "col2", "5.2");
    }
};
scwin.trigger1_onclick = function(e) {
    grd.setCellMaxLength(0, 1, "5.2");
};
scwin.grd_onbeforeedit = function(row, col, value) {
    /*
        console.log("onbeforeedit", row,col,value);
		if(col == 1) {
            if(dataList1.getCellData(row,"col1") == "input") {
                grd.setCellMaxLength(row, "col2", "5.2");
            }
        } 
        */
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.inputTypeCustomObj = {
        calendar: {
            inputType: "calendar"
        },
        radio: {
            inputType: "radio"
        },
        checkbox: {
            inputType: "checkbox"
        },
        input: {
            inputType: "text"
        },
        select: {
            inputType: "select",
            options: {
                viewType: "icon"
            },
            itemSet: {
                nodeset: "data:sel_sample",
                label: "codeLB",
                value: "codeVL"
            }
        }
    };
    //값 변경 시 col2의 inputType을 동적으로 변경한다.
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
